Arguments:
$ErrorActionPreference='Stop'
$ilspy='C:\Users\boqi\.dotnet\tools\ilspycmd.exe'
$cache='artifacts/ecs-relations/cache'
$version='0.1.0-relations.231'
$consumer='tools/SomeEngine.ECS.Relations.AotSmoke/bin/Release/net10.0/win-x64/SomeEngine.ECS.Relations.AotSmoke.dll'
$info=Get-Item -LiteralPath $consumer
'CONSUMER UTC='+$info.LastWriteTimeUtc.ToString('O')+' Length='+$info.Length
$sets=@(
 [pscustomobject]@{Role='Consumer';Path=$consumer;Markers=@('EcsTypeRegistration::RegisterTypes','WeightedTotal8::Matches','EighthEntity::Add','NumberPointValue::Execute','ForwardedMutualPermission::Matches','FillContacts`1::Execute')},
 [pscustomobject]@{Role='Relations';Path="$cache/someengine.ecs.relations/$version/lib/net10.0/SomeEngine.ECS.Relations.dll";Markers=@('ComponentRelation`9::Matches','BitmapRelation`4::Matches','BitmapRelation`4::Evaluate','ICategoryPermission::Evaluate','OneWayPermission::Matches','OneWayPermission::Evaluate','MutualPermission::Matches','MutualPermission::Evaluate','IdentityPermissionOutput`2::Matched','IdentityPermissionOutput`2::Unmatched')},
 [pscustomobject]@{Role='ECS';Path="$cache/someengine.ecs/$version/lib/net10.0/SomeEngine.ECS.dll";Markers=@('GeneratedEcsTypes::RegisterJobStorage','GeneratedEcsTypes::RegisterRelationSchema','JobStorageTypeMetadata`1::Register','JobStorageTypeMetadata`1::get_IsAliasFree','JobStorageTypeMetadata`1::GetIsAliasFree','ComponentMetadata`1::CreateOperations','ComponentInfo::get_IsJobAliasFree','RelationSchema::For','RelationSchemaCache`1::Register','RelationSchemaCache`1::get_Value','QueryCursor::TryReadRef','World::ReadEntityQueryRef')},
 [pscustomobject]@{Role='Systems';Path="$cache/someengine.ecs.systems/$version/lib/net10.0/SomeEngine.ECS.Systems.dll";Markers=@('QueryJobAccess::CopyAccesses')},
 [pscustomobject]@{Role='Physics';Path="$cache/someengine.physics/$version/lib/net10.0/SomeEngine.Physics.dll";Markers=@('SpatialTraversal::Enumerate','SpatialBitmapFilter`5::MatchesLeaves','CountJob`1::Execute','FillJob`1::Execute','CollisionPairBuffer::Fill')}
)
foreach($set in $sets) {
 'ASSEMBLY '+$set.Role+' '+$set.Path
 $il=@(& $ilspy -il $set.Path)
 if($LASTEXITCODE -ne 0) {exit $LASTEXITCODE}
 foreach($marker in $set.Markers) {
  $ends=@(for($i=0;$i -lt $il.Count;$i++) {if($il[$i].Contains('// end of method '+$marker)) {$i}})
  'IL TARGET count='+$ends.Count+' '+$set.Role+' '+$marker
  if($ends.Count -eq 0) {'STOP missing IL marker';exit 2}
  foreach($end in $ends) {
   $begin=$end
   while($begin -gt 0 -and $il[$begin] -notmatch '^\s*\.method\b') {$begin--}
   'BEGIN SELECTED METHOD '+$set.Role+' '+$marker
   $il[$begin..$end]
   'END SELECTED METHOD '+$set.Role+' '+$marker
  }
 }
}

$ErrorActionPreference='Stop'
$llvm='C:\Program Files\LLVM\bin\llvm-objdump.exe'
$obj='tools/SomeEngine.ECS.Relations.AotSmoke/obj/Release/net10.0/win-x64/native/SomeEngine.ECS.Relations.AotSmoke.obj'
$info=Get-Item -LiteralPath $obj
'OBJECT UTC='+$info.LastWriteTimeUtc.ToString('O')+' Length='+$info.Length
$names=@(& $llvm -t $obj | ForEach-Object {if($_ -match '\(sec\s+2\).* 0x[0-9a-f]+ (.+)$') {$Matches[1]}})
$weighted='SomeEngine_ECS_Relations_AotSmoke_SomeEngine_Tools_RelationsSmoke_WeightedTotal8__Matches'
$old=Get-Content -Raw -LiteralPath 'artifacts/benchmark-queue/5f9aaca348574fb49e6bfd9a442f944e/result.json' | ConvertFrom-Json
$arg=@($old.Arguments | Where-Object {$_.StartsWith('--disassemble-symbols=')})
if($arg.Count -ne 1) {'STOP old ComponentRelation exact target count='+$arg.Count;exit 2}
$component=$arg[0].Substring('--disassemble-symbols='.Length)
$points=@($names | Where-Object {$_ -like '*World__ReadEntityQueryRef<*Number_1<*'})
$fill=@($names | Where-Object {$_ -like '*SpatialTraversal__Enumerate*' -and $_ -like '*PairArrayOutput*' -and $_ -like '*DefaultContacts*' -and $_ -like '*MutualCategories*' -and $_ -like '*HairCharacterIndex*'})
'DISCOVERY NumberPoint='+$points.Count+' SpatialFill='+$fill.Count
$points | ForEach-Object {'POINT CANDIDATE '+$_}
$fill | Select-Object -First 6 | ForEach-Object {'FILL CANDIDATE '+$_}
if($points.Count -ne 1 -or $fill.Count -ne 1) {'STOP unique closed roles';exit 2}
$roles=@([pscustomobject]@{Role='Weighted8';Name=$weighted},[pscustomobject]@{Role='Component8';Name=$component},[pscustomobject]@{Role='NumberPoint';Name=$points[0]},[pscustomobject]@{Role='SpatialFill';Name=$fill[0]})
foreach($role in $roles) {
 $hits=@($names | Where-Object {$_ -ceq $role.Name})
 'NATIVE TARGET '+$role.Role+' count='+$hits.Count+' '+$role.Name
 if($hits.Count -ne 1) {'STOP exact target count';exit 2}
}
& $llvm -d -r --no-show-raw-insn ('--disassemble-symbols='+(($roles.Name) -join ',')) $obj
if($LASTEXITCODE -ne 0) {exit $LASTEXITCODE}
